 "content": "def transform(grid):
    """Fill each framed panel's blank cells with the matching colored pattern."""
    h = len(grid)
    w = len(grid[0])
    # The first row is the top frame; its contiguous nonzero prefix is the panel width.
    frame = grid[0][0]
    panel_w = 0
    while panel_w < w and grid[0][panel_w] == frame:
        panel_w += 1
    inner_w = panel_w - 2
    # Horizontal full-frame rows mark the shared boundaries between panels.
    separators = [r for r in range(h) if all(grid[r][c] == frame for c in range(panel_w))]
    if len(separators) < 2:
        raise ValueError('Expected at least two horizontal panel boundaries')
    out = [row[:panel_w] for row in grid]
    canvas_x = panel_w + 1
    for top, bottom in zip(separators, separators[1:]):
        inner_h = bottom - top - 1
        # Capture the color-pattern canvas immediately to the right of the blank gutter.
        source = [grid[top + 1 + r][canvas_x:canvas_x + inner_w] for r in range(inner_h)]
        colors = {v for row in source for v in row if v != 0}
        if len(colors) != 1:
            raise ValueError('Expected one colored pattern in each panel band')
        color = next(iter(colors))
        # The colored pattern occupies exactly the cells that are empty in this frame.
        for r in range(inner_h):
            for c in range(inner_w):
                if grid[top + 1 + r][1 + c] == 0:
                    if source[r][c] != color:
                        raise ValueError('Pattern does not match panel complement')
                    out[top + 1 + r][1 + c] = color
                elif source[r][c] != 0:
                    raise ValueError('Pattern overlaps a frame marker')
    return out
